def extern_closure(self):
    seen, bad, stack = set(), [], []

    def push(ref):
        if ref not in seen:
            seen.add(ref)
            stack.append(ref)
    refs = []

    def collect(o):
        if isinstance(o, dict):
            if o.get("t") == "extern":
                refs.append(o["schemaRef"])
            for v in o.values():
                collect(v)
        elif isinstance(o, list):
            for v in o:
                collect(v)
    collect([self.wire["records"], self.wire["protocols"]])
    for r in refs:
        push(r)
    while stack:
        ref = stack.pop()
        sid, ptr = ref.split("#", 1)
        node = self.docs[sid]
        for part in [p for p in ptr.split("/") if p]:
            node = node[part]

        def scan(o, base):
            if isinstance(o, dict):
                o = {k: v for k, v in o.items() if not k.startswith("x-opensip")}
